void dfs(int u, int p) {
    visited[u] = 1;
    for (int i = 0; i < deg[u]; i++) {
        int v = graph[u][i].to;
        int eid = graph[u][i].id;
        if (v == p) continue;
        if (!visited[v]) {
            parent[v] = u;
            parent_edge[v] = eid;
            dfs(v, u);
        } else if (dir[eid] == 0) {
            // non-tree edge, orient arbitrarily
            dir[eid] = 1; // u -> v
        }
    }
}

void fix_parity(int u) {
    for (int i = 0; i < deg[u]; i++) {
        int v = graph[u][i].to;
        if (v == parent[u]) continue;
        if (parent[v] == u) {
            fix_parity(v);
        }
    }
    if (parent[u] != 0) {
        int eid = parent_edge[u];
        // count outgoing edges from u
        int out = 0;
        for (int i = 0; i < deg[u]; i++) {
            int eid2 = graph[u][i].id;
            int v = graph[u][i].to;
            if (dir[eid2] == 0) continue;
            if ((dir[eid2] == 1 && edge_u[eid2] == u) || (dir[eid2] == -1 && edge_v[eid2] == u))
                out++;
        }
        if (out % 2 == 1) {
            // need to flip parent edge to make even
            if (edge_u[eid] == u)
                dir[eid] = 1; // u -> parent
            else
                dir[eid] = -1; // u -> parent (since u == v in this case)
            // Actually simpler: ensure u -> parent if parity odd
            if (edge_u[eid] == u) dir[eid] = 1;
            else dir[eid] = -1;
        } else {
            if (edge_u[eid] == parent[u]) dir[eid] = 1; // parent -> u
            else dir[eid] = -1;
        }
    }
}

