        edges[ecnt].to = B[i];
        edges[ecnt].id = i;
        edges[ecnt].next = head[A[i]];
        head[A[i]] = ecnt++;

        edges[ecnt].to = A[i];
        edges[ecnt].id = i;
        edges[ecnt].next = head[B[i]];
        head[B[i]] = ecnt++;
    }

    /* Necessary and sufficient condition:
       sum of outdegrees = M, and all outdegrees are even,
       so M must be even. */
    if (M % 2 == 1) {
        printf("-1\n");
        free(A); free(B); free(head); free(edges);
        return 0;
    }

    int *parent = (int *)calloc(N + 1, sizeof(int));
    int *parentEdge = (int *)calloc(N + 1, sizeof(int));
    int *visited = (int *)calloc(N + 1, sizeof(int));
    int *it = (int *)malloc((N + 1) * sizeof(int));
    int *stack = (int *)malloc((N + 1) * sizeof(int));
    int *order = (int *)malloc((N + 1) * sizeof(int));
    int *parity = (int *)calloc(N + 1, sizeof(int)); /* current outdegree parity */
    int *from = (int *)calloc(M + 1, sizeof(int));
    int *to = (int *)calloc(M + 1, sizeof(int));
    int *usedEdge = (int *)calloc(M + 1, sizeof(int));

    /* Build DFS tree iteratively and record finishing order */
    int top = 0, ordsz = 0;
    stack[top++] = 1;
    visited[1] = 1;
    parent[1] = 0;
    for (int i = 1; i <= N; i++) it[i] = head[i];

    while (top > 0) {
        int v = stack[top - 1];
        int e = it[v];
        if (e == -1) {
            order[ordsz++] = v;
            top--;
            continue;
        }
        it[v] = edges[e].next;

        int u = edges[e].to;
        int id = edges[e].id;
        if (usedEdge[id]) continue;
        usedEdge[id] = 1;

        if (!visited[u]) {
            visited[u] = 1;
            parent[u] = v;
            parentEdge[u] = id;
            stack[top++] = u;
        }
    }

    /* reset usedEdge to orient edges */
    for (int i = 1; i <= M; i++) usedEdge[i] = 0;

    /* First orient all non-tree edges from descendant to ancestor.
       This toggles parity of the descendant only. */
    for (int v = 1; v <= N; v++) {
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            int id = edges[e].id;
            if (usedEdge[id]) continue;
            usedEdge[id] = 1;

            if (parent[u] == v || parent[v] == u) {
                continue; /* tree edge, later */
            }

            /* In undirected DFS, non-tree edge is between ancestor/descendant. */
            if (visited[v] && visited[u]) {
                if (v != u) {
                    /* orient from deeper node to shallower node */
                    /* determine by parent relation using a simple climb marker is expensive,
                       but for DFS in undirected graph, when scanning edge (v,u),
                       exactly one is ancestor of the other.
                       We can use discovery order substitute via parent tree not stored.
                       Instead, orient when processing endpoint v:
                       if u is ancestor of v => parent chain of v contains u.
                       To avoid O(NM), we use finish order index. */
                }
            }
        }
    }

    /* Need depths / tin,tout to test ancestor quickly */
    int *depth = (int *)calloc(N + 1, sizeof(int));
    int *tin = (int *)calloc(N + 1, sizeof(int));
    int *tout = (int *)calloc(N + 1, sizeof(int));
    int timer = 0;

    /* iterative DFS for tin/tout on tree only */
    int *st_v = (int *)malloc((2 * N + 5) * sizeof(int));
    int *st_state = (int *)malloc((2 * N + 5) * sizeof(int));
    int sp = 0;
    st_v[sp] = 1; st_state[sp++] = 0;
    while (sp > 0) {
        sp--;
        int v = st_v[sp];
        int state = st_state[sp];
        if (state == 0) {
            tin[v] = ++timer;
            st_v[sp] = v; st_state[sp++] = 1;
            for (int e = head[v]; e != -1; e = edges[e].next) {
                int u = edges[e].to;
                int id = edges[e].id;
                if (parentEdge[u] == id && parent[u] == v) {
                    depth[u] = depth[v] + 1;
                    st_v[sp] = u; st_state[sp++] = 0;
                }
            }
        } else {
            tout[v] = timer;
        }
    }

    for (int i = 1; i <= M; i++) usedEdge[i] = 0;

    for (int v = 1; v <= N; v++) {
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            int id = edges[e].id;
            if (usedEdge[id]) continue;
            usedEdge[id] = 1;

            if (parent[u] == v || parent[v] == u) continue; /* tree edge */

            /* if u is ancestor of v, orient v -> u, else u -> v */
            if (tin[u] <= tin[v] && tout[v] <= tout[u]) {
                from[id] = v;
                to[id] = u;
                parity[v] ^= 1;
            } else {
                from[id] = u;
                to[id] = v;
                parity[u] ^= 1;
            }
        }
    }

    /* Process tree edges bottom-up.
       For child v with parent p:
       if parity[v] is odd, orient v -> p to make v even.
       else orient p -> v. */
    for (int i = 0; i < ordsz; i++) {
        int v = order[i];
        if (v == 1) continue;
        int p = parent[v];
        int id = parentEdge[v];

        if (parity[v]) {
            from[id] = v;
            to[id] = p;
            parity[v] ^= 1;
        } else {
            from[id] = p;
            to[id] = v;
            parity[p] ^= 1;
        }
    }

    /* Since M is even, root parity also becomes even. */
    for (int i = 1; i <= M; i++) {
        printf("%d %d\n", from[i], to[i]);
    }

    free(A); free(B); free(head); free(edges);
    free(parent); free(parentEdge); free(visited); free(it); free(stack); free(order);
    free(parity); free(from); free(to); free(usedEdge);
    free(depth); free(tin); free(tout); free(st_v); free(st_state);

    return 0;
}

