        for (int i = 0; i < M; i++) {
            Edge e = edges[i];
            if (e.dirUToV == 1) {
                sb.append(e.u).append(' ').append(e.v).append('\n');
            } else {
                sb.append(e.v).append(' ').append(e.u).append('\n');
            }
        }
        System.out.print(sb.toString());
    }

    static void dfsBuild(int root) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        ArrayDeque<Integer> itIndex = new ArrayDeque<>();
        visited[root] = true;
        parent[root] = 0;
        stack.push(root);
        itIndex.push(0);
        order[ordSz++] = root;

        while (!stack.isEmpty()) {
            int v = stack.peek();
            int idx = itIndex.pop();

            if (idx == g[v].size()) {
                stack.pop();
                continue;
            }

            itIndex.push(idx + 1);
            AdjEdge ae = g[v].get(idx);
            int to = ae.to;
            int id = ae.id;

            if (!visited[to]) {
                visited[to] = true;
                parent[to] = v;
                parentEdge[to] = id;
                stack.push(to);
                itIndex.push(0);
                order[ordSz++] = to;
            } else if (id != parentEdge[v] && parent[to] != v) {
                // Non-tree edge to an ancestor/already visited vertex.
                // Orient from current vertex v to 'to' exactly once.
                if (edges[id].dirUToV == -1) {
                    Edge e = edges[id];
                    if (e.u == v && e.v == to) e.dirUToV = 1;
                    else e.dirUToV = 0;
                    outParity[v] ^= 1;
                }
            }
        }
    }
